import java.util.List;

class Solution {
    public int countMatches(List<List<String>> items, String ruleKey, String ruleValue) {
        int count = 0;
        for (List<String> item : items) {
            if (matches(item, ruleKey, ruleValue)) {
                count++;
            }
        }
        return count;
    }

    private boolean matches(List<String> item, String ruleKey, String ruleValue) {
        if (ruleKey.equals("type")) {
            return item.get(0).equals(ruleValue);
        }
        if (ruleKey.equals("color")) {
            return item.get(1).equals(ruleValue);
        }
        return item.get(2).equals(ruleValue);
    }
}
